"""Admission (capacity + deficient cut) and schedule compilation."""
from collections import defaultdict
from cutcheck import find_deficient_cut
from maxflow import Dinic


# ------------------------------------------------------------------ admission
def capacity_denial(svc, pid, s, e, env):
    ticks = set([s])
    for b in svc.bookings.values():
        if b.live and s < b.s < e:
            ticks.add(b.s)
    for t in sorted(ticks):
        for l, bl in env.items():
            used = svc.used_at(l, t)
            if used + bl > svc.caps[l]:
                return {'status': 'denied', 'id': pid, 'rev': svc.rev,
                        'kind': 'capacity', 'link': l, 'time': t,
                        'used': used + bl, 'capacity': svc.caps[l]}
    return None


def compile_prepare(svc, pid, s, e, period, parts, env):
    cert = capacity_denial(svc, pid, s, e, env)
    if cert is not None:
        return cert
    caps = [period * env.get(l, 0) for l in range(len(svc.links))]
    r = dict(parts)
    cut = find_deficient_cut(svc.n, svc.links, caps, parts, r)
    if cut is not None:
        return {'status': 'denied', 'id': pid, 'rev': svc.rev,
                'kind': 'cut', 'cut': cut}
    plan = build_plan(svc.n, svc.links, caps, parts, r)
    if plan is None:
        plan = build_plan_flat(svc.n, svc.links, caps, parts, r)
    if plan is None:
        return {'status': 'denied', 'id': pid, 'rev': svc.rev,
                'kind': 'cut', 'cut': _fallback_cut(svc.n, svc.links, caps,
                                                   parts, r)}
    return {'status': 'prepared', 'id': pid, 'rev': svc.rev, 'plan': plan}


def _fallback_cut(n, links, caps, parts, r):
    cut = find_deficient_cut(n, links, caps, parts, r)
    if cut is not None:
        return cut
    return [parts[0][0]]


# ------------------------------------------------------------------ path router
class Router(object):
    def __init__(self, n, links, caps):
        self.n = n
        self.links = links
        self.res = list(caps)
        m = len(links)
        self.tail = [links[a // 2][1] if a % 2 == 0 else links[a // 2][0]
                     for a in range(2 * m)]
        self.head = [links[a // 2][0] if a % 2 == 0 else links[a // 2][1]
                     for a in range(2 * m)]

    def route(self, src, dst, amount, allowed):
        """Route `amount` units src->dst over vertices in `allowed` (set).

        Returns a list of (path(list of arc ids), amount) or None.
        """
        if amount == 0:
            return []
        verts = sorted(allowed)
        idx = {v: i for i, v in enumerate(verts)}
        if src not in idx or dst not in idx:
            return None
        g = Dinic(len(verts) + 2)
        S = len(verts)
        T = S + 1
        arcs = []
        for a in range(len(self.res)):
            if (self.res[a] > 0 and self.tail[a] in idx
                    and self.head[a] in idx):
                arcs.append((a, g.add(idx[self.tail[a]], idx[self.head[a]],
                                      self.res[a])))
        g.add(S, idx[src], amount)
        g.add(idx[dst], T, amount)
        got = g.maxflow(S, T)
        if got != amount:
            return None
        flowmap = {}
        for (a, i) in arcs:
            f = self.res[a] - g.cap[i]
            if f > 0:
                flowmap[a] = f
                self.res[a] -= f
        return _decompose(src, dst, flowmap, amount, self.tail, self.head)


def _decompose(src, dst, flowmap, amount, tail, head):
    """Split a flow into src->dst paths (list of (path, amount))."""
    out = []
    remaining = dict(flowmap)
    outadj = defaultdict(list)
    for a, amt in remaining.items():
        if amt > 0:
            outadj[tail[a]].append(a)
    while amount > 0:
        # DFS from src to dst on positive-flow arcs
        stack = [src]
        prev = {src: None}
        found = False
        while stack:
            x = stack.pop()
            if x == dst:
                found = True
                break
            for a in list(outadj[x]):
                if remaining.get(a, 0) <= 0:
                    continue
                y = head[a]
                if y in prev:
                    continue
                prev[y] = a
                stack.append(y)
        if not found:
            return None
        # walk back
        path = []
        x = dst
        while prev[x] is not None:
            a = prev[x]
            path.append(a)
            x = tail[a]
        path.reverse()
        bottleneck = min(remaining[a] for a in path)
        for a in path:
            remaining[a] -= bottleneck
        out.append((path, bottleneck))
        amount -= bottleneck
    if amount != 0:
        return None
    return out


# ------------------------------------------------------------------ hierarchy
class Node(object):
    __slots__ = ('parts', 'region', 'dem', 'u', 'w', 'children', 'leaf')

    def __init__(self, parts, region):
        self.parts = parts
        self.region = region
        self.dem = sum(rv for (_v, rv) in parts)
        self.u = None
        self.w = None
        self.children = None
        self.leaf = None


def _mincut_side(vertices, links, caps, src, dst):
    idx = {v: i for i, v in enumerate(vertices)}
    g = Dinic(len(vertices))
    for l, (u, v) in enumerate(links):
        if u in idx and v in idx and caps[l] > 0:
            g.add(idx[u], idx[v], caps[l])
            g.add(idx[v], idx[u], caps[l])
    g.maxflow(idx[src], idx[dst])
    mark = g.reachable(idx[src])
    A = set([v for v in vertices if mark[idx[v]]])
    B = set(vertices) - A
    return A, B


def build_hierarchy(vertices, parts, links, caps):
    node = Node(list(parts), set(vertices))
    if len(parts) == 1:
        node.leaf = parts[0][0]
        return node
    p0 = parts[0][0]
    best = None
    for (q, _rv) in parts:
        if q == p0:
            continue
        A, B = _mincut_side(vertices, links, caps, p0, q)
        if p0 not in A:
            A, B = B, A
        pa = [x for x in parts if x[0] in A]
        pb = [x for x in parts if x[0] in B]
        if not pa or not pb:
            continue
        score = abs(len(pa) - len(pb))
        if best is None or score < best[0]:
            best = (score, A, B, pa, pb)
    if best is None:
        half = len(parts) // 2
        pa = parts[:half]
        pb = parts[half:]
        A = set([x[0] for x in pa])
        B = set([x[0] for x in pb])
        best = (0, A, B, pa, pb)
    _s, A, B, pa, pb = best
    node.children = (build_hierarchy(A, pa, links, caps),
                     build_hierarchy(B, pb, links, caps))
    return node


def _leaves(node):
    if node.children is None:
        return [node.leaf]
    out = []
    for c in node.children:
        out.extend(_leaves(c))
    return out


# ------------------------------------------------------------------ plan build
def build_plan(n, links, caps, parts, r):
    D = sum(r.values())
    if D <= 0:
        return None
    root = build_hierarchy(list(range(n)), parts, links, caps)
    router = Router(n, links, caps)
    partset = set([v for (v, _rv) in parts])
    edges = []

    def walk(node, topdown):
        if node.children is None:
            return True
        ca, cb = node.children
        if topdown:
            if not _route_node(node, ca, cb, router, partset, edges):
                return False
            return walk(ca, True) and walk(cb, True)
        if not (walk(ca, False) and walk(cb, False)):
            return False
        return _route_node(node, ca, cb, router, partset, edges)

    ok = walk(root, False)
    if not ok:
        router = Router(n, links, caps)
        edges = []
        ok = walk(root, True)
    if not ok:
        return None

    trees = _build_trees(parts, edges)
    if trees is None:
        return None
    routes, recipes = _build_routes(edges, links)
    if routes is None:
        return None
    return {'trees': trees, 'routes': routes, 'recipes': recipes}


def _route_node(node, ca, cb, router, partset, edges):
    ra = ca.dem
    rb = cb.dem
    la = _leaves(ca)
    lb = _leaves(cb)
    region = node.region
    # order candidates by a rough distance preference
    cands = []
    for u in la:
        for w in lb:
            cands.append((u, w))
    chosen = None
    for (u, w) in cands:
        allowed = set(region) - (partset - set([u, w]))
        if ra > 0:
            f1 = router.route(u, w, ra, allowed)
            if f1 is None:
                continue
        else:
            f1 = []
        if rb > 0:
            f2 = router.route(w, u, rb, allowed)
            if f2 is None:
                for (p, amt) in f1:
                    for a in p:
                        router.res[a] += amt
                continue
        else:
            f2 = []
        chosen = (u, w, f1, f2)
        break
    if chosen is None:
        return False
    u, w, f1, f2 = chosen
    node.u = u
    node.w = w
    edges.append((u, w, ra, rb, f1, f2))
    return True


def _build_trees(parts, edges):
    adj = defaultdict(list)
    for (u, w, ra, rb, _f1, _f2) in edges:
        adj[u].append((w, ra))
        adj[w].append((u, rb))
    trees = []
    for (v, rv) in parts:
        if rv <= 0:
            continue
        parent = {v: None}
        edgelist = []
        order = [v]
        qi = 0
        while qi < len(order):
            x = order[qi]
            qi += 1
            for (y, _amt) in adj.get(x, []):
                if y not in parent:
                    parent[y] = x
                    edgelist.append([x, y])
                    order.append(y)
        if len(parent) != len(parts):
            return None
        trees.append([v, rv, edgelist])
    return trees


def _build_routes(edges, links):
    recipes = []
    memo = {}
    routes = []
    for (u, w, ra, rb, f1, f2) in edges:
        if ra > 0:
            if not _emit(u, w, ra, f1, routes, recipes, memo):
                return None, None
        if rb > 0:
            if not _emit(w, u, rb, f2, routes, recipes, memo):
                return None, None
    return routes, recipes


def _emit(u, w, amount, flows, routes, recipes, memo):
    total = 0
    for (path, amt) in flows:
        rid = _recipe(path, recipes, memo)
        if rid is None:
            return False
        routes.append([u, w, amt, rid])
        total += amt
    return total == amount


def _recipe(path, recipes, memo):
    if not path:
        return None
    node = None
    for a in path:
        single = (0, a // 2, a % 2)
        if single not in memo:
            memo[single] = len(recipes)
            recipes.append([0, a // 2, a % 2])
        cur = memo[single]
        if node is None:
            node = cur
        else:
            key = (node, cur)
            if key not in memo:
                memo[key] = len(recipes)
                recipes.append([1, node, cur])
            node = memo[key]
    return node


# ------------------------------------------------------------------ fallback
def build_plan_flat(n, links, caps, parts, r):
    """Star-per-root construction (each root sends directly to all others)."""
    D = sum(r.values())
    router = Router(n, links, caps)
    partset = set([v for (v, _rv) in parts])
    routes = []
    recipes = []
    memo = {}
    trees = []
    for (v, rv) in parts:
        if rv <= 0:
            continue
        edgelist = []
        for (w, _rw) in parts:
            if w == v:
                continue
            allowed = set(range(n)) - (partset - set([v, w]))
            fl = router.route(v, w, rv, allowed)
            if fl is None:
                return None
            for (path, amt) in fl:
                rid = _recipe(path, recipes, memo)
                routes.append([v, w, amt, rid])
            edgelist.append([v, w])
        trees.append([v, rv, edgelist])
    return {'trees': trees, 'routes': routes, 'recipes': recipes}
